#include <bits/stdc++.h>
using namespace std;

int fmod = 998244353;
vector<long long> fact, ifact;

long long fmul(long long a, long long b) {
    return (a * b) % fmod;
}

long long fpow(long long a, long long b) {
    long long res = 1;
    long long base = a;
    long long exp = b;
    while (exp > 0) {
        if (exp & 1) res = fmul(res, base);
        base = fmul(base, base);
        exp >>= 1;
    }
    return res;
}

long long ifact_func(int x) {
    static vector<long long> ifact_cache;
    if (x < (int)ifact_cache.size() && ifact_cache[x] != -1) {
        return ifact_cache[x];
    } else {
        long long res = fpow(fact[x], fmod - 2);
        if (x >= (int)ifact_cache.size()) {
            ifact_cache.resize(x + 1, -1);
        }
        ifact_cache[x] = res;
        return res;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long kl;
    cin >> n >> kl;
    if (kl >= n) {
        cout << 0 << "\n";
        return 0;
    }
    int k = (int)kl;
    fact.resize(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = fmul(fact[i - 1], i);
    }
    long long ans = 0;
    int mult = 1;
    for (int i = 0; i <= n - k; i++, mult = -mult) {
        long long add = mult * fmul(fpow(n - k - i, n), fmul(fact[n - k], fmul(ifact_func(i), ifact_func(n - k - i))));
        add %= fmod;
        if (add < 0) add += fmod;
        ans += add;
        if (ans >= fmod) ans -= fmod;
    }
    long long res = fmul(fmul(ans, fact[n]), fmul(ifact_func(k), ifact_func(n - k))) % fmod;
    if (k == 0) {
        cout << res << "\n";
    } else {
        cout << fmul(res, 2) << "\n";
    }
    return 0;
}
